// AUTO-GENERATED from lib/time.js and lib/scheduler.js by scripts/build-workflow.js.
// Do not edit here - edit lib/ and re-run the builder.
const crypto = require('crypto');
function sha256(value) { return crypto.createHash('sha256').update(String(value), 'utf8').digest('hex'); }

/**
 * Timezone-aware date/time helpers for the LinkedIn automation scheduler.
 *
 * Pure functions with no external dependencies. scripts/build-workflow.js
 * inlines this file verbatim into the n8n Code nodes, and tests/ exercises it
 * directly, so the tested code is exactly the code that runs inside n8n.
 */

const MS_PER_DAY = 86400000;

/** Google Sheets serial-date epoch (serial 0 == 1899-12-30). */
const SHEETS_EPOCH_MS = Date.UTC(1899, 11, 30);

function pad2(n) {
  return String(n).padStart(2, '0');
}

/**
 * Wall-clock parts for `date` as observed in `timeZone`.
 * Intl does the offset/DST arithmetic so we never hand-roll it.
 */
function zonedParts(date, timeZone) {
  const fmt = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hour12: false,
  });
  const p = {};
  for (const part of fmt.formatToParts(date)) p[part.type] = part.value;
  // Some ICU builds emit "24" for midnight under hour12:false.
  const hour = p.hour === '24' ? '00' : p.hour;
  return {
    ymd: p.year + '-' + p.month + '-' + p.day,
    year: Number(p.year),
    month: Number(p.month),
    day: Number(p.day),
    hour: Number(hour),
    minute: Number(p.minute),
    second: Number(p.second),
    minutes: Number(hour) * 60 + Number(p.minute),
  };
}

/** Current date in `timeZone` as YYYY-MM-DD. */
function todayInZone(timeZone, now) {
  return zonedParts(now || new Date(), timeZone).ymd;
}

/**
 * True when `value` is an IANA timezone this runtime recognizes.
 *
 * Worth checking because B1 is often part of a merged cell: Sheets can report
 * the merge's value ("11.00AM") for every cell it covers, and feeding that to
 * Intl throws a RangeError that would take the whole Code node down.
 */
function isValidTimeZone(value) {
  if (!value || typeof value !== 'string') return false;
  try {
    new Intl.DateTimeFormat('en-CA', { timeZone: value }).format(new Date());
    return true;
  } catch (_) {
    return false;
  }
}

/** Build YYYY-MM-DD, rejecting impossible calendar dates like 31/02. */
function isoOrNull(year, month, day) {
  if (!(year >= 1970 && year <= 9999)) return null;
  if (!(month >= 1 && month <= 12)) return null;
  if (!(day >= 1 && day <= 31)) return null;
  const probe = new Date(Date.UTC(year, month - 1, day));
  if (probe.getUTCMonth() !== month - 1 || probe.getUTCDate() !== day) return null;
  return year + '-' + pad2(month) + '-' + pad2(day);
}

/**
 * Normalize a Column B date cell to YYYY-MM-DD, or null if unparseable.
 *
 * Google Sheets hands the same cell back in several shapes depending on the
 * node's value-render mode and the user's locale, so all of them are accepted:
 *   - Date object / ISO datetime string  (already parsed by n8n)
 *   - serial number                      (UNFORMATTED_VALUE)
 *   - "DD/MM/YYYY", "D/M/YY"             (the format the spec documents)
 *   - "YYYY-MM-DD"                       (ISO date)
 *   - "03 Oct 2026", "Oct 3, 2026"       (locale text)
 *
 * Slash dates are read DAY-FIRST per the spec: 03/10/2026 is 3 October 2026,
 * never 10 March. Reading it the other way would publish on the wrong day.
 */
function parseSheetDate(value, timeZone) {
  if (value === null || value === undefined) return null;

  if (value instanceof Date) {
    if (Number.isNaN(value.getTime())) return null;
    return zonedParts(value, timeZone).ymd;
  }

  if (typeof value === 'number' && Number.isFinite(value)) {
    // Serial days already carry wall-clock time, so read UTC parts directly
    // rather than shifting them through a timezone a second time.
    const d = new Date(SHEETS_EPOCH_MS + Math.floor(value) * MS_PER_DAY);
    return d.getUTCFullYear() + '-' + pad2(d.getUTCMonth() + 1) + '-' + pad2(d.getUTCDate());
  }

  const raw = String(value).trim();
  if (!raw) return null;

  // A serial number that arrived as text.
  if (/^\d+(\.\d+)?$/.test(raw) && Number(raw) > 1000) {
    return parseSheetDate(Number(raw), timeZone);
  }

  // ISO date, optionally with a time component.
  let m = raw.match(/^(\d{4})-(\d{2})-(\d{2})(?:[T ]|$)/);
  if (m) return isoOrNull(Number(m[1]), Number(m[2]), Number(m[3]));

  // Day-first slash/dot/dash dates.
  m = raw.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{2,4})$/);
  if (m) {
    let year = Number(m[3]);
    if (m[3].length === 2) year += year < 70 ? 2000 : 1900;
    return isoOrNull(year, Number(m[2]), Number(m[1]));
  }

  // Fall back to the engine's parser for textual months ("03 Oct 2026").
  const parsed = new Date(raw);
  if (!Number.isNaN(parsed.getTime())) {
    // Non-ISO date-only strings are parsed as LOCAL midnight by the engine, so
    // read local parts back. Converting through a timezone here would shift the
    // date by a day on any host whose offset differs from the target zone.
    // (ISO "YYYY-MM-DD" is parsed as UTC, but the regex above already caught it.)
    if (!/[T:]|[+-]\d{2}:?\d{2}$|Z$/.test(raw)) {
      return parsed.getFullYear() + '-' + pad2(parsed.getMonth() + 1) + '-' + pad2(parsed.getDate());
    }
    return zonedParts(parsed, timeZone).ymd;
  }

  return null;
}

function fractionToMinutes(n) {
  if (n < 0) return null;
  const minutes = Math.round((n % 1) * 1440);
  return minutes >= 1440 ? 0 : minutes;
}

/**
 * Normalize an A1 posting-time cell to minutes since midnight, or null.
 *
 * Accepts "11:00 AM", "11:00", "11:00:00", "1:05 pm", "11 AM", a Sheets time
 * fraction (0.4583333 == 11:00), and the 1899-12-30T11:00:00 datetime shape
 * the Sheets API returns for time-formatted cells.
 */
function parseClockTime(value, timeZone) {
  if (value === null || value === undefined) return null;

  if (value instanceof Date) {
    if (Number.isNaN(value.getTime())) return null;
    // Time-only cells come back anchored to the Sheets epoch in UTC.
    if (value.getTime() < Date.UTC(1900, 0, 1)) {
      return value.getUTCHours() * 60 + value.getUTCMinutes();
    }
    return zonedParts(value, timeZone).minutes;
  }

  if (typeof value === 'number' && Number.isFinite(value)) {
    return fractionToMinutes(value);
  }

  const raw = String(value).trim();
  if (!raw) return null;

  // Sheets epoch datetime standing in for a time-only cell.
  const epochMatch = raw.match(/^1899-12-30T(\d{2}):(\d{2})/);
  if (epochMatch) return Number(epochMatch[1]) * 60 + Number(epochMatch[2]);

  if (/^\d*\.\d+$/.test(raw)) return fractionToMinutes(Number(raw));

  const m = raw.match(/^(\d{1,2})[:.](\d{2})(?::(\d{2}))?\s*([AaPp])?\.?[Mm]?\.?$/);
  if (m) {
    let hour = Number(m[1]);
    const minute = Number(m[2]);
    if (minute > 59) return null;
    const meridiem = m[4] ? m[4].toLowerCase() : null;
    if (meridiem) {
      if (hour < 1 || hour > 12) return null;
      if (meridiem === 'p' && hour !== 12) hour += 12;
      if (meridiem === 'a' && hour === 12) hour = 0;
    } else if (hour > 23) {
      return null;
    }
    return hour * 60 + minute;
  }

  // "11 AM" with no minutes.
  const hourOnly = raw.match(/^(\d{1,2})\s*([AaPp])\.?[Mm]\.?$/);
  if (hourOnly) {
    let hour = Number(hourOnly[1]);
    if (hour < 1 || hour > 12) return null;
    const meridiem = hourOnly[2].toLowerCase();
    if (meridiem === 'p' && hour !== 12) hour += 12;
    if (meridiem === 'a' && hour === 12) hour = 0;
    return hour * 60;
  }

  return null;
}

/** "11:00 AM" style rendering, for logs and sheet writes. */
function formatMinutes(minutes) {
  const h = Math.floor(minutes / 60);
  const suffix = h < 12 ? 'AM' : 'PM';
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return h12 + ':' + pad2(minutes % 60) + ' ' + suffix;
}

/** Sheet-friendly timestamp: DD/MM/YYYY HH:MM:SS in the configured zone. */
function formatTimestamp(date, timeZone) {
  const p = zonedParts(date, timeZone);
  return pad2(p.day) + '/' + pad2(p.month) + '/' + p.year + ' ' +
    pad2(p.hour) + ':' + pad2(p.minute) + ':' + pad2(p.second);
}

/**
 * Sheet interpretation + due-row selection.
 *
 * Everything here is a pure function over the raw `values` matrix that the
 * Google Sheets API returns for the whole range (A:L). Keeping it pure is what
 * makes the acceptance matrix in tests/ runnable without n8n, Google, or a
 * clock. scripts/build-workflow.js inlines this file into the n8n Code node.
 */


const STATUS = {
  PENDING: 'Pending',
  PROCESSING: 'Processing',
  RESEARCHING: 'Researching',
  GENERATING: 'Generating',
  IMAGE_READY: 'ImageReady',
  PUBLISHING: 'Publishing',
  POSTED: 'Posted',
  FAILED: 'Failed',
  BLOCKED: 'Blocked',
};

/** Statuses that mean "a run already owns this row". */
const IN_FLIGHT = [
  STATUS.PROCESSING, STATUS.RESEARCHING, STATUS.GENERATING,
  STATUS.IMAGE_READY, STATUS.PUBLISHING,
];

/** Column letter -> zero-based index, for the A:L contract in docs/sheet-schema.md. */
const COL = {
  day: 0, date: 1, topic: 2, status: 3, post: 4, image: 5,
  postId: 6, postedAt: 7, error: 8, attempts: 9, token: 10, key: 11,
};

const DEFAULTS = {
  timezone: 'Asia/Kolkata',
  staleMinutes: 30,
  maxAttempts: 3,
  allowMultiplePerDay: false,
};

function cell(row, index) {
  if (!Array.isArray(row)) return '';
  const v = row[index];
  if (v === null || v === undefined) return '';
  return v;
}

function text(row, index) {
  return String(cell(row, index)).trim();
}

/** Case/space-insensitive status comparison; blank counts as Pending. */
function normalizeStatus(value) {
  const raw = String(value === null || value === undefined ? '' : value)
    .trim().toLowerCase().replace(/[\s_-]+/g, '');
  if (!raw) return STATUS.PENDING;
  for (const key of Object.keys(STATUS)) {
    if (STATUS[key].toLowerCase() === raw) return STATUS[key];
  }
  // Tolerate common hand-typed variants rather than silently skipping the row.
  if (raw === 'done' || raw === 'published' || raw === 'complete') return STATUS.POSTED;
  if (raw === 'todo' || raw === 'new' || raw === 'queued') return STATUS.PENDING;
  if (raw === 'error') return STATUS.FAILED;
  return value ? String(value).trim() : STATUS.PENDING;
}

function parseBool(value, fallback) {
  if (value === null || value === undefined || value === '') return fallback;
  if (typeof value === 'boolean') return value;
  const raw = String(value).trim().toLowerCase();
  if (['true', 'yes', 'y', '1', 'on', 'enabled'].includes(raw)) return true;
  if (['false', 'no', 'n', '0', 'off', 'disabled'].includes(raw)) return false;
  return fallback;
}

/**
 * Work out where the content table starts.
 *
 * The spec puts control values in row 1 and a header row somewhere below it,
 * but an existing sheet may differ. Rather than assume, find the first row that
 * looks like headers ("Date"/"Topic"/"Status" in the expected columns) and take
 * the data as everything after it. Falls back to "row 1 is control, data starts
 * at row 2" when no header row is recognizable.
 */
function detectLayout(values) {
  const limit = Math.min(values.length, 10);
  for (let i = 0; i < limit; i++) {
    const row = values[i] || [];
    const b = text(row, COL.date).toLowerCase();
    const c = text(row, COL.topic).toLowerCase();
    const d = text(row, COL.status).toLowerCase();
    const hits = (b === 'date' ? 1 : 0) + (c === 'topic' ? 1 : 0) + (d === 'status' ? 1 : 0);
    if (hits >= 2) {
      return { headerRowIndex: i, dataStartIndex: i + 1, detected: true };
    }
  }
  return { headerRowIndex: null, dataStartIndex: 1, detected: false };
}

/**
 * Read the control cells from row 1.
 * `env` supplies defaults so the sheet can leave B1/C1/D1/E1 blank.
 */
function readSettings(values, env) {
  const e = env || {};
  const row1 = values[0] || [];

  // B1 is frequently inside a merged block with A1, in which case Sheets may
  // report the posting time here too. Only accept a real IANA zone.
  const declaredZone = text(row1, 1);
  const timezone = isValidTimeZone(declaredZone) ? declaredZone
    : (isValidTimeZone(e.TIMEZONE) ? e.TIMEZONE : DEFAULTS.timezone);
  const postingMinutes = parseClockTime(cell(row1, 0), timezone);

  return {
    timezone,
    postingMinutes,
    postingTimeRaw: text(row1, 0),
    timezoneSource: isValidTimeZone(declaredZone) ? 'B1'
      : (declaredZone ? 'default (B1 "' + declaredZone + '" is not a valid timezone)' : 'default'),
    autoPublish: parseBool(cell(row1, 2), parseBool(e.AUTO_PUBLISH, false)),
    enableResearch: parseBool(cell(row1, 3), parseBool(e.ENABLE_RESEARCH, true)),
    enableImage: parseBool(cell(row1, 4), parseBool(e.ENABLE_IMAGE, true)),
    staleMinutes: Number(e.STALE_MINUTES) > 0 ? Number(e.STALE_MINUTES) : DEFAULTS.staleMinutes,
    maxAttempts: Number(e.MAX_ATTEMPTS) > 0 ? Number(e.MAX_ATTEMPTS) : DEFAULTS.maxAttempts,
    allowMultiplePerDay: parseBool(e.ALLOW_MULTIPLE_PER_DAY, DEFAULTS.allowMultiplePerDay),
  };
}

/** Collapse a topic to a stable form so trivial edits do not change its identity. */
function normalizeTopic(topic) {
  return String(topic || '').trim().toLowerCase().replace(/\s+/g, ' ');
}

/**
 * Deterministic identity for "this topic, on this date, at this time".
 * `sha256` is injected so this file stays dependency-free for the n8n sandbox.
 */
function buildIdempotencyKey(isoDate, topic, postingMinutes, sha256) {
  return sha256([isoDate || '', normalizeTopic(topic), String(postingMinutes)].join('|'));
}

/** Turn the raw matrix into typed row objects carrying their 1-based sheet row number. */
function parseRows(values, layout, settings, sha256) {
  const out = [];
  for (let i = layout.dataStartIndex; i < values.length; i++) {
    const raw = values[i] || [];
    const topic = text(raw, COL.topic);
    const dateCell = cell(raw, COL.date);
    if (!topic && !String(dateCell).trim()) continue; // genuinely blank row

    const isoDate = parseSheetDate(dateCell, settings.timezone);
    const attemptsRaw = text(raw, COL.attempts);
    out.push({
      rowNumber: i + 1,
      rowIndex: i,
      day: text(raw, COL.day),
      dateRaw: dateCell,
      isoDate,
      topic,
      status: normalizeStatus(cell(raw, COL.status)),
      statusRaw: text(raw, COL.status),
      generatedPost: text(raw, COL.post),
      imageRef: text(raw, COL.image),
      linkedinPostId: text(raw, COL.postId),
      postedAt: text(raw, COL.postedAt),
      error: text(raw, COL.error),
      attempts: /^\d+$/.test(attemptsRaw) ? Number(attemptsRaw) : 0,
      runToken: text(raw, COL.token),
      idempotencyKey: text(raw, COL.key) ||
        (sha256 ? buildIdempotencyKey(isoDate, topic, settings.postingMinutes, sha256) : ''),
    });
  }
  return out;
}

/** Minutes between `postedAt`-style sheet timestamps and now; Infinity if unreadable. */
function minutesSince(timestamp, timezone, now) {
  if (!timestamp) return Infinity;
  const m = String(timestamp).trim()
    .match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?/);
  if (!m) {
    const parsed = new Date(timestamp);
    if (Number.isNaN(parsed.getTime())) return Infinity;
    return (now.getTime() - parsed.getTime()) / 60000;
  }
  // The stamp is wall-clock in `timezone`; compare it against now rendered the
  // same way, so no offset arithmetic is needed and DST cannot skew it.
  const p = zonedParts(now, timezone);
  const nowMins = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second) / 60000;
  const thenMins = Date.UTC(
    Number(m[3]), Number(m[2]) - 1, Number(m[1]),
    Number(m[4]), Number(m[5]), Number(m[6] || 0),
  ) / 60000;
  return nowMins - thenMins;
}

/**
 * Pick at most one row to process this tick.
 *
 * Returns { due: false, reason } or { due: true, row, action, ... }.
 * `action` is 'process' for a fresh claim or 'recover' for a stale in-flight row.
 */
function selectDueRow(values, env, now, sha256) {
  const clock = now || new Date();
  const layout = detectLayout(values);
  const settings = readSettings(values, env);

  if (settings.postingMinutes === null) {
    return { due: false, reason: 'A1 posting time is missing or unparseable', settings, layout };
  }

  const today = todayInZone(settings.timezone, clock);
  const nowMinutes = zonedParts(clock, settings.timezone).minutes;
  const rows = parseRows(values, layout, settings, sha256);

  // Rows that already published, keyed by identity, block any twin from running.
  const publishedKeys = new Set();
  for (const r of rows) {
    if (r.linkedinPostId && r.idempotencyKey) publishedKeys.add(r.idempotencyKey);
  }

  if (!settings.allowMultiplePerDay) {
    const postedToday = rows.find(function (r) {
      return r.isoDate === today && r.linkedinPostId;
    });
    if (postedToday) {
      return {
        due: false,
        reason: 'A post already published today (row ' + postedToday.rowNumber + ')',
        settings, layout, today, nowMinutes,
      };
    }
  }

  const candidates = [];
  for (const row of rows) {
    if (row.isoDate !== today) continue;
    if (row.linkedinPostId) continue;          // never republish (spec §5, §14)
    if (!row.topic) continue;
    if (row.status === STATUS.POSTED) continue;
    if (row.status === STATUS.BLOCKED) continue;
    if (row.status === STATUS.FAILED && row.attempts >= settings.maxAttempts) continue;
    if (nowMinutes < settings.postingMinutes) continue;

    // A twin row already published this exact date+topic+time.
    if (publishedKeys.has(row.idempotencyKey)) {
      candidates.push({ row: row, action: 'block', reason: 'Duplicate of an already-published row' });
      continue;
    }

    if (IN_FLIGHT.includes(row.status)) {
      // Only reclaim once the row has clearly been abandoned, and only because
      // we confirmed above that no Post ID exists for it. The claim timestamp
      // rides along in the run token as "<token>@<DD/MM/YYYY HH:MM:SS>"; a row
      // in flight with no readable stamp is treated as stale, since every claim
      // this workflow makes writes one.
      const stamp = row.runToken.includes('@') ? row.runToken.split('@')[1] : '';
      const age = minutesSince(stamp, settings.timezone, clock);
      if (age >= settings.staleMinutes) {
        candidates.push({ row: row, action: 'recover', reason: 'Stale ' + row.status + ' for ' + Math.round(age) + ' min' });
      }
      continue;
    }

    if (row.status === STATUS.PENDING || row.status === STATUS.FAILED) {
      candidates.push({ row: row, action: 'process', reason: 'Due and pending' });
    }
  }

  if (!candidates.length) {
    return { due: false, reason: 'No due row', settings, layout, today, nowMinutes };
  }

  // Earliest row wins (spec §6: "process only the earliest row by row number").
  candidates.sort(function (a, b) { return a.row.rowNumber - b.row.rowNumber; });
  const chosen = candidates[0];

  return {
    due: true,
    action: chosen.action,
    reason: chosen.reason,
    row: chosen.row,
    settings, layout, today, nowMinutes,
    pendingCount: candidates.length,
  };
}

const response = $input.first().json;
const values = Array.isArray(response.values) ? response.values : [];

const env = {
  TIMEZONE: $env.TIMEZONE,
  AUTO_PUBLISH: $env.AUTO_PUBLISH,
  ENABLE_RESEARCH: $env.ENABLE_RESEARCH,
  ENABLE_IMAGE: $env.ENABLE_IMAGE,
  STALE_MINUTES: $env.STALE_MINUTES,
  MAX_ATTEMPTS: $env.MAX_ATTEMPTS,
  ALLOW_MULTIPLE_PER_DAY: $env.ALLOW_MULTIPLE_PER_DAY,
};

const now = new Date();
const decision = selectDueRow(values, env, now, sha256);

if (!decision.due) {
  return [{ json: { due: false, reason: decision.reason, today: decision.today || null, nowMinutes: decision.nowMinutes ?? null } }];
}

// AUTO_PUBLISH is the master safety switch from spec Phase 10. When it is off
// the row is still selected and reported, but nothing downstream runs.
if (!decision.settings.autoPublish) {
  return [{ json: { due: false, reason: "AUTO_PUBLISH is false; row " + decision.row.rowNumber + " (" + decision.row.topic + ") would have been processed", dryRun: true } }];
}

const row = decision.row;
const runToken = crypto.randomUUID().slice(0, 8) + "@" + formatTimestamp(now, decision.settings.timezone);

// Content hashes already in the sheet, so the writer stage can reject repeats.
const previousHashes = [];
for (let i = decision.layout.dataStartIndex; i < values.length; i++) {
  const existing = (values[i] || [])[COL.post];
  if (existing) previousHashes.push(sha256(String(existing).toLowerCase().replace(/\s+/g, " ").trim()));
}

return [{ json: {
  due: true,
  action: decision.action,
  reason: decision.reason,
  rowNumber: row.rowNumber,
  topic: row.topic,
  isoDate: row.isoDate,
  dateRaw: String(row.dateRaw),
  status: row.status,
  attempts: row.attempts,
  idempotencyKey: row.idempotencyKey,
  runToken: runToken,
  previousHashes: previousHashes,
  sheetName: $env.GOOGLE_SHEET_NAME || "Sheet1",
  settings: decision.settings,
  startedAt: formatTimestamp(now, decision.settings.timezone),
} }];

// Google Sheets has no atomic compare-and-swap, so we write our run token
// and read it back. If another scheduler run claimed the same row in the
// gap, its token is what survives and we stand down. This narrows the race
// to the write window rather than eliminating it - see README "Concurrency".
const ctx = $('Select Due Row').first().json;
const rows = $input.first().json.values || [];
const row = rows[0] || [];
const tokenInSheet = String(row[10] || "").trim();
const postIdInSheet = String(row[6] || "").trim();

if (postIdInSheet) {
  return [{ json: { owned: false, reason: "Row already has a LinkedIn Post ID: " + postIdInSheet, rowNumber: ctx.rowNumber } }];
}
if (tokenInSheet !== ctx.runToken) {
  return [{ json: { owned: false, reason: "Row claimed by another run (" + tokenInSheet + ")", rowNumber: ctx.rowNumber } }];
}

return [{ json: Object.assign({}, ctx, { owned: true }) }];

// AUTO-GENERATED from lib/validate.js. Edit lib/ and re-run the builder.
/**
 * Parsing and validation of Gemini output, plus the gate that decides whether a
 * post is allowed to reach LinkedIn.
 *
 * The bias throughout is to refuse rather than to repair: spec §15 says "Do not
 * publish if validation fails", and a half-fixed post is worse than no post.
 */

/** LinkedIn rejects commentary longer than this (FIELD_LENGTH_TOO_LONG). */
const MAX_COMMENTARY = 3000;
const MIN_POST_LENGTH = 180;

/**
 * Last-resort repair of almost-valid JSON.
 *
 * Models reliably produce two defects that JSON.parse rejects outright:
 * trailing commas, and raw newlines/tabs inside string literals (which happens
 * whenever a code sample is embedded in a field). Both are unambiguous to fix
 * without guessing at intent, so they are repaired rather than discarding an
 * otherwise complete research result. Anything more damaged than this is left
 * to fail - a half-understood post is worse than no post.
 */
function repairJson(text) {
  let out = '';
  let inString = false;
  let escaped = false;

  for (let i = 0; i < text.length; i++) {
    const ch = text[i];

    if (escaped) { out += ch; escaped = false; continue; }
